function generateCredentialsTxt(props) {
  const today = props.dateStr || (/* @__PURE__ */ new Date()).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
  const orderNo = String(props.orderId).startsWith("#") ? props.orderId : `#${props.orderId}`;
  let content = `========================================\r
`;
  content += `YOUUHOST DIGITAL RECEIPT & ACCESS\r
`;
  content += `========================================\r
`;
  content += `Order ID     : ${orderNo}\r
`;
  content += `Product      : ${props.productName}\r
`;
  content += `Customer     : ${props.recipientName || "Valued Customer"}\r
`;
  content += `Delivered On : ${today}\r
`;
  content += `----------------------------------------\r
`;
  content += `DELIVERED CREDENTIALS:\r
`;
  content += `----------------------------------------\r
`;
  const creds = props.credentials && props.credentials.length > 0 ? props.credentials : [
    "username: youuhost_admin",
    "password: VpsP@ss#2026!"
  ];
  creds.forEach((item, index2) => {
    if (creds.length > 1) {
      content += `[Item ${index2 + 1}]\r
`;
    }
    content += `${item.trim()}\r
\r
`;
  });
  content += `----------------------------------------\r
`;
  content += `Support: https://t.me/youuhost_support\r
`;
  content += `========================================\r
`;
  return Buffer.from(content, "utf-8");
}
function sanitizeCurrencyAmount(amountRaw, fallbackDefault = "LKR 14,990.00") {
  if (!amountRaw || typeof amountRaw !== "string") return fallbackDefault;
  let str = amountRaw.trim();
  if (str.includes("(") || str.includes("\u2248") || str.includes("~")) {
    const parts = str.split(/[\(≈~]/);
    str = (parts[0] || "").trim();
  }
  str = str.replace(/[^\x20-\x7E]/g, "").trim();
  if (str.toUpperCase().includes("LKR") || str.toUpperCase().includes("RS")) {
    const numMatch = str.replace(/,/g, "").match(/(\d+(\.\d+)?)/);
    if (numMatch) {
      const val = parseFloat(numMatch[1]);
      if (str.toUpperCase().includes("RS")) {
        return `Rs. ${val.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} LKR`;
      }
      return `LKR ${val.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    }
  }
  if (str.toUpperCase().includes("USD") || str.includes("$")) {
    const numMatch = str.replace(/,/g, "").match(/(\d+(\.\d+)?)/);
    if (numMatch) {
      const val = parseFloat(numMatch[1]);
      return `$${val.toFixed(2)} USD`;
    }
  }
  return str || fallbackDefault;
}
